/**
 * Loads labels by primary key with no tenant predicate, so a stale picker id
 * that belongs to another workspace is distinguishable from a missing id.
 * Callers must `assertOrgScope` on every row.
 */
export async function findLabelsByIds(
  labelIds: readonly LabelId[],
): Promise<readonly IssueLabel[]> {
  if (labelIds.length === 0) return [];
  const rows = getDb()
    .select()
    .from(labels)
    .where(inArray(labels.id, [...labelIds]))
    .all();
  return rows.map(toLabel);
}

/** Batched lookup keyed by issue id, so list views avoid an N+1. */
export async function listLabelsForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Readonly<Record<string, readonly IssueLabel[]>>> {
  if (issueIds.length === 0) return {};

  const rows = getDb()
    .select({ issueId: issueLabels.issueId, label: labels })
    .from(issueLabels)
    .innerJoin(
      labels,
      and(eq(labels.id, issueLabels.labelId), orgPredicate(labels.orgId, orgId)),
    )
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .all();

