 * Reference checks for a change made inside one workspace.
 *
 * A row that exists under another organization is a tenant-scope violation.
 * Anything missing, archived, deleted, outside the current project, not a
 * top-level comment, or not a current member is not found. Callers must run
 * these before writing, so a refusal leaves every row and event untouched.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { CommentId, IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Assignee and project lead: a current, active member of this workspace. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
}

/** Parent issue: live, and in the same project as the issue being created. */
export async function assertParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await issueRepo.findIssueByIdUnscoped(parentId);
  if (parent === null) {
    throw new NotFoundError("Issue", parentId);
  }
  assertOrgScope(actor, parent.orgId);
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Every label id must be a label that belongs to the actor's workspace. */
export async function assertWorkspaceLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const found = await labelRepo.findLabelsByIds(labelIds);
  const byId = new Map(found.map((label) => [label.id, label]));

  for (const labelId of labelIds) {
    const label = byId.get(labelId);
    if (label === undefined) {
      throw new NotFoundError("Label", labelId);
    }
    assertOrgScope(actor, label.orgId);
  }
}

